INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-01-01-romania-scope-expansion-working-days', '2026-01-01', '2026-01', 'From 1 January 2026, domestic supplies to VAT-registered customers without a fixed establishment in Romania — previously exempted — now fall within RO e-Factura''s scope, and the general transmission deadline shifts from calendar days to 5 working days.', '<h3>🇷🇴 Romania closes a scope gap and shifts the transmission deadline to working days</h3>
<p>Two changes take effect together today within Romania''s RO e-Factura system, and it''s worth understanding both since they interact in practice. First, a scope gap has closed: domestic supplies to VAT-registered customers without a fixed establishment in Romania — a category previously exempted from the mandate — now fall within RO e-Factura''s clearance requirements like any other in-scope domestic transaction. Second, and genuinely easy to get wrong: the general transmission deadline has shifted from calendar days to 5 working days. A number of English-language explainers still cite the earlier calendar-day rule, which is no longer the correct operating assumption.</p>
<p>The distinction between calendar and working days matters more than it might first appear, particularly around Romanian public holidays and weekends, where a calendar-day countdown and a working-day countdown can diverge by several days depending on when in the month an invoice is issued. Romania''s underlying system remains a genuine clearance model for B2B and B2G transactions — ANAF validates and digitally seals invoices before they gain legal validity, a materially different mechanism from countries where a transmission deadline is simply an administrative reporting requirement layered on top of an invoice that''s already legally valid on issuance.</p>
<p><strong>What this means for your team:</strong> if you supply VAT-registered Romanian customers without a Romanian fixed establishment, confirm today whether that flow is now correctly routed through RO e-Factura — this is a genuine new compliance obligation, not a continuation of a prior exemption. Separately, if your internal deadline tracking still counts calendar days rather than working days, update it now: the difference compounds around holiday periods in ways that are easy to miscalculate manually.</p>', 'https://mfinante.gov.ro/en/web/efactura/informatii-tehnice', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-01-01-romania-scope-expansion-working-days', id FROM countries WHERE name_en = 'Romania';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-romania-scope-expansion-working-days', 'en', 'Romania closes a scope gap and shifts the transmission deadline to working days', 'From 1 January 2026, domestic supplies to VAT-registered customers without a fixed establishment in Romania — previously exempted — now fall within RO e-Factura''s scope, and the general transmission deadline shifts from calendar days to 5 working days.', '<h3>🇷🇴 Romania closes a scope gap and shifts the transmission deadline to working days</h3>
<p>Two changes take effect together today within Romania''s RO e-Factura system, and it''s worth understanding both since they interact in practice. First, a scope gap has closed: domestic supplies to VAT-registered customers without a fixed establishment in Romania — a category previously exempted from the mandate — now fall within RO e-Factura''s clearance requirements like any other in-scope domestic transaction. Second, and genuinely easy to get wrong: the general transmission deadline has shifted from calendar days to 5 working days. A number of English-language explainers still cite the earlier calendar-day rule, which is no longer the correct operating assumption.</p>
<p>The distinction between calendar and working days matters more than it might first appear, particularly around Romanian public holidays and weekends, where a calendar-day countdown and a working-day countdown can diverge by several days depending on when in the month an invoice is issued. Romania''s underlying system remains a genuine clearance model for B2B and B2G transactions — ANAF validates and digitally seals invoices before they gain legal validity, a materially different mechanism from countries where a transmission deadline is simply an administrative reporting requirement layered on top of an invoice that''s already legally valid on issuance.</p>
<p><strong>What this means for your team:</strong> if you supply VAT-registered Romanian customers without a Romanian fixed establishment, confirm today whether that flow is now correctly routed through RO e-Factura — this is a genuine new compliance obligation, not a continuation of a prior exemption. Separately, if your internal deadline tracking still counts calendar days rather than working days, update it now: the difference compounds around holiday periods in ways that are easy to miscalculate manually.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-06-01-romania-law-88-scope-changes', '2026-06-01', '2026-06', 'Romania''s Law No. 88, effective 1 June 2026, removes individual farmers and personal-code-identified taxpayers from the mandatory RO e-Factura register, while moving NGOs, foundations, political parties, and religious institutions from optional to fully mandatory use.', '<h3>🇷🇴 Law No. 88 reshapes who must use RO e-Factura — exemptions for some, new mandates for others</h3>
<p>Romania''s Parliament approved Law No. 88 on 29 May 2026, bringing into effect amendments to Government Emergency Ordinance No. 128/2024 that genuinely move scope in both directions at once — worth understanding carefully rather than assuming it''s a simple loosening or tightening in one clear direction. Individual farmers and taxpayers identified by personal numerical code (CNP) are no longer mandated to use RO e-Factura at all — though they can still choose to join the optional registry if they wish, rather than being excluded from the system entirely.</p>
<p>Moving the other way: non-profit organisations — associations, foundations, political parties, and religious institutions — shift from optional to fully mandatory use, once their one-year grace period (which ran through 30 June 2025) has already elapsed. Any of these entities engaging in genuine economic activity are now squarely within the mandatory RO e-Factura register, not merely invited to participate voluntarily. Separately, ANAF has also updated Form 082 — the sole formal mechanism for registering in the mandatory register — specifically to accommodate individuals whose activities now fall under mandatory scope through this same legislative change, with a clear registration cut-off tied to when their economic activity actually began.</p>
<p><strong>What this means for your team:</strong> don''t assume this change only removed obligations — if your organisation is a non-profit, association, foundation, or religious institution conducting economic activity, confirm your mandatory registration status directly rather than continuing to treat RO e-Factura as optional based on outdated guidance. Individual farmers and CNP-identified taxpayers newly exempted should also confirm their actual status directly with ANAF, since remaining in the optional registry by choice carries different practical implications than exiting the system altogether.</p>', 'https://mfinante.gov.ro/en/web/efactura/informatii-tehnice', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-06-01-romania-law-88-scope-changes', id FROM countries WHERE name_en = 'Romania';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-06-01-romania-law-88-scope-changes', 'en', 'Law No. 88 reshapes who must use RO e-Factura — exemptions for some, new mandates for others', 'Romania''s Law No. 88, effective 1 June 2026, removes individual farmers and personal-code-identified taxpayers from the mandatory RO e-Factura register, while moving NGOs, foundations, political parties, and religious institutions from optional to fully mandatory use.', '<h3>🇷🇴 Law No. 88 reshapes who must use RO e-Factura — exemptions for some, new mandates for others</h3>
<p>Romania''s Parliament approved Law No. 88 on 29 May 2026, bringing into effect amendments to Government Emergency Ordinance No. 128/2024 that genuinely move scope in both directions at once — worth understanding carefully rather than assuming it''s a simple loosening or tightening in one clear direction. Individual farmers and taxpayers identified by personal numerical code (CNP) are no longer mandated to use RO e-Factura at all — though they can still choose to join the optional registry if they wish, rather than being excluded from the system entirely.</p>
<p>Moving the other way: non-profit organisations — associations, foundations, political parties, and religious institutions — shift from optional to fully mandatory use, once their one-year grace period (which ran through 30 June 2025) has already elapsed. Any of these entities engaging in genuine economic activity are now squarely within the mandatory RO e-Factura register, not merely invited to participate voluntarily. Separately, ANAF has also updated Form 082 — the sole formal mechanism for registering in the mandatory register — specifically to accommodate individuals whose activities now fall under mandatory scope through this same legislative change, with a clear registration cut-off tied to when their economic activity actually began.</p>
<p><strong>What this means for your team:</strong> don''t assume this change only removed obligations — if your organisation is a non-profit, association, foundation, or religious institution conducting economic activity, confirm your mandatory registration status directly rather than continuing to treat RO e-Factura as optional based on outdated guidance. Individual farmers and CNP-identified taxpayers newly exempted should also confirm their actual status directly with ANAF, since remaining in the optional registry by choice carries different practical implications than exiting the system altogether.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-07-01-romania-sme-enforcement-arrives', '2026-07-01', '2026-07', 'The deferred enforcement window for Romanian small and medium-sized businesses under €500,000 annual turnover has now ended — full RO e-Factura compliance, including penalties, applies to this population from today.', '<h3>🇷🇴 SME enforcement deadline arrives — businesses under €500,000 turnover now face full compliance</h3>
<p>Romania''s RO e-Factura clearance system has been mandatory for most domestic B2B flows since July 2024, but the government recognised early on that full, immediate enforcement placed a disproportionate operational burden on the smallest businesses. Enforcement — not the underlying legal obligation itself, but the actual application of penalties — was deferred for businesses with annual turnover below €500,000, first to an earlier date and then extended further. That deferral window closes today: full enforcement now applies to this population exactly as it already has for larger businesses.</p>
<p>Worth being precise about what changes today versus what was already true: the legal requirement to use RO e-Factura for in-scope transactions hasn''t changed for this group — only the enforcement of penalties for non-compliance was ever deferred. Romania''s penalty structure is genuinely tiered by taxpayer size, and for B2B transactions specifically, a 15% penalty of the invoice value applies to issuers or recipients handling invoices outside the system. That''s a materially significant figure for a small business, not a token administrative fine.</p>
<p><strong>What this means for your team:</strong> if your business has been operating under the assumption that the small-business deferral gives ongoing breathing room, that assumption stopped being true today, not at some point in the future. Confirm your invoicing actually routes through RO e-Factura correctly now, rather than discovering a gap only once ANAF penalty enforcement is genuinely live for businesses your size.</p>', 'https://mfinante.gov.ro/en/web/efactura/informatii-tehnice', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-07-01-romania-sme-enforcement-arrives', id FROM countries WHERE name_en = 'Romania';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-01-romania-sme-enforcement-arrives', 'en', 'SME enforcement deadline arrives — businesses under €500,000 turnover now face full compliance', 'The deferred enforcement window for Romanian small and medium-sized businesses under €500,000 annual turnover has now ended — full RO e-Factura compliance, including penalties, applies to this population from today.', '<h3>🇷🇴 SME enforcement deadline arrives — businesses under €500,000 turnover now face full compliance</h3>
<p>Romania''s RO e-Factura clearance system has been mandatory for most domestic B2B flows since July 2024, but the government recognised early on that full, immediate enforcement placed a disproportionate operational burden on the smallest businesses. Enforcement — not the underlying legal obligation itself, but the actual application of penalties — was deferred for businesses with annual turnover below €500,000, first to an earlier date and then extended further. That deferral window closes today: full enforcement now applies to this population exactly as it already has for larger businesses.</p>
<p>Worth being precise about what changes today versus what was already true: the legal requirement to use RO e-Factura for in-scope transactions hasn''t changed for this group — only the enforcement of penalties for non-compliance was ever deferred. Romania''s penalty structure is genuinely tiered by taxpayer size, and for B2B transactions specifically, a 15% penalty of the invoice value applies to issuers or recipients handling invoices outside the system. That''s a materially significant figure for a small business, not a token administrative fine.</p>
<p><strong>What this means for your team:</strong> if your business has been operating under the assumption that the small-business deferral gives ongoing breathing room, that assumption stopped being true today, not at some point in the future. Confirm your invoicing actually routes through RO e-Factura correctly now, rather than discovering a gap only once ANAF penalty enforcement is genuinely live for businesses your size.</p>');
